{"command":"cd /workspace && cat > internal/hosts/types.go <<'EOF'
// Package hosts implements the data model, parser and writer of a hosts
// file managed by hostctl.
package hosts

import (
	"errors"
	"net"
)

// Status values of a profile or a route.
const (
	Enabled  = "on"
	Disabled = "off"
)

// DefaultProfile is the name used for the unmanaged content of the file.
const DefaultProfile = "default"

var (
	// ErrUnknownProfile is returned when a profile can not be found.
	ErrUnknownProfile = errors.New("unknown profile name")
	// ErrNoProfiles is returned when the file does not contain any profile.
	ErrNoProfiles = errors.New("there are no profiles")
)

// Route groups all host names that point to the same IP.
type Route struct {
	IP        net.IP
	HostNames []string
}

// Line is a single line of the default (unmanaged) section.
// It is either a route (IP + first host name) or a raw text line.
type Line struct {
	IsRoute bool
	Raw     string
	IP      net.IP
	Host    string
	Status  string
}

// String renders the line as it will be written to the file.
func (l Line) String() string {
	if !l.IsRoute {
		return l.Raw
	}
	s := l.IP.String() + " " + l.Host
	if l.Status == Disabled {
		return "# " + s
	}
	return s
}

// Profile is a named group of routes.
type Profile struct {
	Name   string
	Status string
	IPList []string
	Routes map[string]*Route
}

// NewProfile creates an empty profile.
func NewProfile(name, status string) *Profile {
	return &Profile{
		Name:   name,
		Status: status,
		Routes: map[string]*Route{},
	}
}

// AddRoute adds host names to the given ip, avoiding duplicates.
func (p *Profile) AddRoute(ip net.IP, hosts []string) {
	key := ip.String()
	r, ok := p.Routes[key]
	if !ok {
		r = &Route{IP: ip}
		p.Routes[key] = r
		p.IPList = append(p.IPList, key)
	}
	for _, h := range hosts {
		if !containsString(r.HostNames, h) {
			r.HostNames = append(r.HostNames, h)
		}
	}
}

// AddRoutes merges all routes of another profile into this one.
func (p *Profile) AddRoutes(other *Profile) {
	for _, key := range other.IPList {
		r := other.Routes[key]
		p.AddRoute(r.IP, r.HostNames)
	}
}

// RemoveHostNames removes the given host names from every route.
// Routes without host names are dropped.
func (p *Profile) RemoveHostNames(hosts []string) {
	var list []string
	for _, key := range p.IPList {
		r := p.Routes[key]
		var keep []string
		for _, h := range r.HostNames {
			if !containsString(hosts, h) {
				keep = append(keep, h)
			}
		}
		r.HostNames = keep
		if len(keep) == 0 {
			delete(p.Routes, key)
			continue
		}
		list = append(list, key)
	}
	p.IPList = list
}

// Empty reports whether the profile has no routes.
func (p *Profile) Empty() bool {
	return len(p.IPList) == 0
}

// Content is the parsed representation of a hosts file.
type Content struct {
	Default      []Line
	ProfileNames []string
	Profiles     map[string]*Profile
}

// NewContent creates an empty content.
func NewContent() *Content {
	return &Content{Profiles: map[string]*Profile{}}
}

func containsString(list []string, s string) bool {
	for _, v := range list {
		if v == s {
			return true
		}
	}
	return false
}
EOF"}

