{"command":"cd /workspace && cat > internal/hosts/parser.go <<'EOF'
package hosts

import (
	"bufio"
	"bytes"
	"io"
	"net"
	"regexp"
	"strings"
)

const bannerText = "# Content under this line is handled by hostctl. DO NOT EDIT."

const bannerBlock = "##################################################################\n" +
	bannerText + "\n" +
	"##################################################################\n"

var profileStartRe = regexp.MustCompile(`# profile.(on|off)\s+([a-z0-9\-_.\s]+)`)

func isEndMarker(line string) bool {
	return strings.Contains(strings.ToLower(line), "# end")
}

// ParseRouteLine parses a line like "[# ]IP host1 host2 # comment".
// It returns the ip, the host names, whether the line was commented out
// and whether the line is a valid route at all.
func ParseRouteLine(line string) (net.IP, []string, bool, bool) {
	fields := strings.Fields(line)
	disabled := false
	if len(fields) > 0 && fields[0] == "#" {
		disabled = true
		fields = fields[1:]
	}
	if len(fields) < 2 {
		return nil, nil, false, false
	}
	ip := net.ParseIP(fields[0])
	if ip == nil {
		return nil, nil, false, false
	}
	var hosts []string
	for _, f := range fields[1:] {
		if idx := strings.Index(f, "#"); idx >= 0 {
			if idx > 0 {
				hosts = append(hosts, f[:idx])
			}
			break
		}
		hosts = append(hosts, f)
	}
	if len(hosts) == 0 {
		return nil, nil, false, false
	}
	return ip, hosts, disabled, true
}

func readLines(r io.Reader) ([]string, error) {
	var lines []string
	s := bufio.NewScanner(r)
	for s.Scan() {
		lines = append(lines, s.Text())
	}
	return lines, s.Err()
}

// Parse reads a complete hosts file.
func Parse(r io.Reader) (*Content, error) {
	lines, err := readLines(r)
	if err != nil {
		return nil, err
	}
	c := NewContent()
	current := ""
	for i := 0; i < len(lines); i++ {
		line := strings.TrimSpace(lines[i])

		if m := profileStartRe.FindStringSubmatch(line); m != nil {
			name := strings.TrimSpace(m[2])
			status := Enabled
			if m[1] == "off" {
				status = Disabled
			}
			c.Profiles[name] = NewProfile(name, status)
			c.ProfileNames = append(c.ProfileNames, name)
			current = name
			continue
		}

		if isEndMarker(line) {
			current = ""
			continue
		}

		if current != "" {
			if ip, hosts, _, ok := ParseRouteLine(line); ok {
				c.Profiles[current].AddRoute(ip, hosts)
			}
			continue
		}

		if i > 0 && strings.Contains(line, bannerText) {
			// drop the banner block: previous line, this one and the next
			c.Default = c.Default[:len(c.Default)-1]
			i++
			continue
		}

		if ip, hosts, disabled, ok := ParseRouteLine(line); ok {
			status := Enabled
			if disabled {
				status = Disabled
			}
			c.Default = append(c.Default, Line{IsRoute: true, IP: ip, Host: hosts[0], Status: status})
			continue
		}
		c.Default = append(c.Default, Line{Raw: line})
	}
	return c, nil
}

// ParseProfile reads every valid route line of r into a new profile.
func ParseProfile(name string, r io.Reader) (*Profile, error) {
	lines, err := readLines(r)
	if err != nil {
		return nil, err
	}
	p := NewProfile(name, Enabled)
	for _, l := range lines {
		if ip, hosts, _, ok := ParseRouteLine(l); ok {
			p.AddRoute(ip, hosts)
		}
	}
	return p, nil
}

// Bytes renders the content as a hosts file.
func (c *Content) Bytes() []byte {
	var b bytes.Buffer
	var lines []string
	for _, l := range c.Default {
		s := l.String()
		if s == "" && len(lines) > 0 && lines[len(lines)-1] == "" {
			continue
		}
		lines = append(lines, s)
	}
	for len(lines) > 0 && lines[len(lines)-1] == "" {
		lines = lines[:len(lines)-1]
	}
	for _, l := range lines {
		b.WriteString(l)
		b.WriteString("\n")
	}
	b.WriteString("\n")
	b.WriteString(bannerBlock)
	for _, name := range c.ProfileNames {
		p := c.Profiles[name]
		b.WriteString("\n# profile." + p.Status + " " + p.Name + "\n")
		for _, key := range p.IPList {
			r := p.Routes[key]
			for _, h := range r.HostNames {
				if p.Status == Disabled {
					b.WriteString("# ")
				}
				b.WriteString(key + " " + h + "\n")
			}
		}
		b.WriteString("# end\n")
	}
	return b.Bytes()
}
EOF"}

