	var b bytes.Buffer
	var lines []string
	for _, l := range c.Default {
		s := l.String()
		if s == "" && len(lines) > 0 && lines[len(lines)-1] == "" {
			continue
		}
		lines = append(lines, s)
	}
	for len(lines) > 0 && lines[len(lines)-1] == "" {
		lines = lines[:len(lines)-1]
	}
	for _, l := range lines {
		b.WriteString(l)
		b.WriteString("\n")
	}
	b.WriteString("\n")
	b.WriteString(bannerBlock)
	for _, name := range c.ProfileNames {
		p := c.Profiles[name]
		b.WriteString("\n# profile." + p.Status + " " + p.Name + "\n")
		for _, key := range p.IPList {
			r := p.Routes[key]
			for _, h := range r.HostNames {
				if p.Status == Disabled {
					b.WriteString("# ")
				}
				b.WriteString(key + " " + h + "\n")
			}
		}
		b.WriteString("# end\n")
	}
	return b.Bytes()
}
EOF

