// Disable disables the given profiles.
func (c *Content) Disable(names []string) error { return c.setStatus(names, Disabled) }

// EnableOnly enables the given profiles and disables every other.
func (c *Content) EnableOnly(names []string) { c.setStatusOnly(names, Enabled, Disabled) }

// DisableOnly disables the given profiles and enables every other.
func (c *Content) DisableOnly(names []string) { c.setStatusOnly(names, Disabled, Enabled) }

