func (c *Content) Toggle(names []string) error {
	for _, name := range names {
		p, ok := c.Profiles[name]
		if !ok {
			return ErrUnknownProfile
		}
		if p.Status == Enabled {
			p.Status = Disabled
		} else {
			p.Status = Enabled
		}
	}
	return nil
}

func (c *Content) removeProfile(name string) {
	delete(c.Profiles, name)
	var names []string
	for _, n := range c.ProfileNames {
		if n != name {
			names = append(names, n)
		}
	}
	c.ProfileNames = names
}

// RemoveProfiles removes the given profiles.
func (c *Content) RemoveProfiles(names []string) error {
	for _, name := range names {
		if _, ok := c.Profiles[name]; !ok {
			return ErrUnknownProfile
		}
		c.removeProfile(name)
	}
	return nil
}

// RemoveAllProfiles removes every profile and returns their names.
func (c *Content) RemoveAllProfiles() ([]string, error) {
	if len(c.ProfileNames) == 0 {
		return nil, ErrNoProfiles
	}
	names := c.ProfileNames
	c.ProfileNames = nil
	c.Profiles = map[string]*Profile{}
	return names, nil
}

// AddProfile merges the profile into an existing one or appends it.
func (c *Content) AddProfile(p *Profile) {
	if cur, ok := c.Profiles[p.Name]; ok {
		cur.AddRoutes(p)
		return
	}
	c.Profiles[p.Name] = p
	c.ProfileNames = append(c.ProfileNames, p.Name)
}

// ReplaceProfile removes any profile with the same name and appends p.
func (c *Content) ReplaceProfile(p *Profile) {
	if _, ok := c.Profiles[p.Name]; ok {
		c.removeProfile(p.Name)
	}
	c.Profiles[p.Name] = p
	c.ProfileNames = append(c.ProfileNames, p.Name)
}

// AddDomains adds domains pointing to ip to a profile, creating it if needed.
func (c *Content) AddDomains(name string, ip net.IP, domains []string) {
	p, ok := c.Profiles[name]
	if !ok {
		p = NewProfile(name, Enabled)
		c.Profiles[name] = p
		c.ProfileNames = append(c.ProfileNames, name)
	}
	p.AddRoute(ip, domains)
}

// RemoveDomains removes domains from a profile. When the profile ends up
// empty it is removed and true is returned.
func (c *Content) RemoveDomains(name string, domains []string) (bool, error) {
	p, ok := c.Profiles[name]
	if !ok {
		return false, ErrUnknownProfile
	}
	p.RemoveHostNames(domains)
	if p.Empty() {
		c.removeProfile(name)
		return true, nil
	}
	return false, nil
}
