{"command":"cd /workspace && cat > internal/render/tablewriter.go <<'EOF'
package render

import (
	"fmt"
	"io"
	"math"
	"regexp"
	"strings"

	"github.com/mattn/go-runewidth"
)

// Alignment values.
const (
	alignDefault = iota
	alignCenter
	alignRight
	alignLeft
)

const (
	headerRowIdx   = -1
	maxColWidth    = 30
	defaultPenalty = 1e5
)

var (
	ansiRe    = regexp.MustCompile("\033\\[(?:[0-9]{1,3}(?:;[0-9]{1,3})*)?[m|K]")
	decimalRe = regexp.MustCompile(`^-?(?:\d{1,3}(?:,\d{3})*|\d+)(?:\.\d+)?$`)
	percentRe = regexp.MustCompile(`^-?\d+\.?\d*$%$`)
)

type borders struct {
	Left, Right, Top, Bottom bool
}

// table is a small ascii table writer.
type table struct {
	out          io.Writer
	headers      [][]string
	lines        [][][]string
	separators   map[int]bool
	cs           map[int]int
	rs           map[int]int
	autoWrap     bool
	autoFmt      bool
	border       borders
	pCenter      string
	pRow         string
	pColumn      string
	hdrLine      bool
	hAlign       int
	align        int
	noWhiteSpace bool
	tablePadding string
	newLine      string
}

func newTable(out io.Writer) *table {
	return &table{
		out:        out,
		separators: map[int]bool{},
		cs:         map[int]int{},
		rs:         map[int]int{},
		autoWrap:   true,
		autoFmt:    true,
		border:     borders{Left: true, Right: true, Top: true, Bottom: true},
		pCenter:    "+",
		pRow:       "-",
		pColumn:    "|",
		hdrLine:    true,
		hAlign:     alignDefault,
		align:      alignDefault,
		newLine:    "\n",
	}
}

func displayWidth(s string) int {
	return runewidth.StringWidth(ansiRe.ReplaceAllLiteralString(s, ""))
}

func conditionString(cond bool, valid, inValid string) string {
	if cond {
		return valid
	}
	return inValid
}

func isNumOrSpace(r rune) bool {
	return ('0' <= r && r <= '9') || r == ' '
}

func title(name string) string {
	origLen := len(name)
	rs := []rune(name)
	for i, r := range rs {
		switch r {
		case '_':
			rs[i] = ' '
		case '.':
			if (i != 0 && !isNumOrSpace(rs[i-1])) || (i != len(rs)-1 && !isNumOrSpace(rs[i+1])) {
				rs[i] = ' '
			}
		}
	}
	name = string(rs)
	name = strings.TrimSpace(name)
	if len(name) == 0 && origLen > 0 {
		name = " "
	}
	return strings.ToUpper(name)
}

func padCenter(s, pad string, width int) string {
	gap := width - displayWidth(s)
	if gap > 0 {
		gapLeft := int(math.Ceil(float64(gap / 2)))
		gapRight := gap - gapLeft
		return strings.Repeat(pad, gapLeft) + s + strings.Repeat(pad, gapRight)
	}
	return s
}

func padRight(s, pad string, width int) string {
	gap := width - displayWidth(s)
	if gap > 0 {
		return s + strings.Repeat(pad, gap)
	}
	return s
}

func padLeft(s, pad string, width int) string {
	gap := width - displayWidth(s)
	if gap > 0 {
		return strings.Repeat(pad, gap) + s
	}
	return s
}

func padFunc(align int) func(string, string, int) string {
	switch align {
	case alignLeft:
		return padRight
	case alignRight:
		return padLeft
	}
	return padCenter
}

func wrapWords(words []string, spc, lim, pen int) [][]string {
	n := len(words)
	length := make([][]int, n)
	for i := 0; i < n; i++ {
		length[i] = make([]int, n)
		length[i][i] = runewidth.StringWidth(words[i])
		for j := i + 1; j < n; j++ {
			length[i][j] = length[i][j-1] + spc + runewidth.StringWidth(words[j])
		}
	}
	nbrk := make([]int, n)
	cost := make([]int, n)
	for i := range cost {
		cost[i] = math.MaxInt32
	}
	for i := n - 1; i >= 0; i-- {
		if length[i][n-1] <= lim {
			cost[i] = 0
			nbrk[i] = n
		} else {
			for j := i + 1; j < n; j++ {
				d := lim - length[i][j-1]
				c := d*d + cost[j]
				if length[i][j-1] > lim {
					c += pen
				}
				if c < cost[i] {
					cost[i] = c
					nbrk[i] = j
				}
			}
		}
	}
	var lines [][]string
	i := 0
	for i < n {
		lines = append(lines, words[i:nbrk[i]])
		i = nbrk[i]
	}
	return lines
}

func wrapString(s string, lim int) ([]string, int) {
	words := strings.Split(strings.Replace(s, "\n", " ", -1), " ")
	var lines []string
	max := 0
	for _, v := range words {
		max = displayWidth(v)
		if max > lim {
			lim = max
		}
	}
	for _, line := range wrapWords(words, 1, lim, defaultPenalty) {
		lines = append(lines, strings.Join(line, " "))
	}
	return lines, lim
}

func (t *table) parseDimension(str string, colKey, rowKey int) []string {
	raw := strings.Split(str, "\n")
	maxWidth := 0
	for _, line := range raw {
		if w := displayWidth(line); w > maxWidth {
			maxWidth = w
		}
	}
	if t.autoWrap {
		if maxWidth > maxColWidth {
			maxWidth = maxColWidth
		}
		newMaxWidth := maxWidth
		newRaw := make([]string, 0, len(raw))
		for i, para := range raw {
			paraLines, _ := wrapString(para, maxWidth)
			for _, line := range paraLines {
				if w := displayWidth(line); w > newMaxWidth {
					newMaxWidth = w
				}
			}
			if i > 0 {
				newRaw = append(newRaw, " ")
			}
			newRaw = append(newRaw, paraLines...)
		}
		raw = newRaw
		maxWidth = newMaxWidth
	}
	if v, ok := t.cs[colKey]; !ok || v < maxWidth || v == 0 {
		t.cs[colKey] = maxWidth
	}
	h := len(raw)
	if v, ok := t.rs[rowKey]; !ok || v < h || v == 0 {
		t.rs[rowKey] = h
	}
	return raw
}

func (t *table) setHeader(keys []string) {
	for i, v := range keys {
		t.headers = append(t.headers, t.parseDimension(v, i, headerRowIdx))
	}
}

func (t *table) append(row []string) {
	n := len(t.lines)
	line := [][]string{}
	for i, v := range row {
		line = append(line, t.parseDimension(v, i, n))
	}
	t.lines = append(t.lines, line)
}

// addSeparator marks a separator line before the next appended row.
func (t *table) addSeparator() {
	t.separators[len(t.lines)] = true
}

func (t *table) numRows() int { return len(t.lines) }

func (t *table) render() {
	if t.border.Top {
		t.printLine(true)
	}
	t.printHeading()
	for i, lines := range t.lines {
		if t.separators[i] {
			t.printLine(true)
		}
		t.printRow(lines, i)
	}
	if t.border.Bottom {
		t.printLine(true)
	}
}

func (t *table) printLine(nl bool) {
	fmt.Fprint(t.out, t.pCenter)
	for i := 0; i < len(t.cs); i++ {
		v := t.cs[i]
		fmt.Fprintf(t.out, "%s%s%s%s", t.pRow, strings.Repeat(t.pRow, v), t.pRow, t.pCenter)
	}
	if nl {
		fmt.Fprint(t.out, t.newLine)
	}
}

func (t *table) printHeading() {
	if len(t.headers) < 1 {
		return
	}
	end := len(t.cs) - 1
	pf := padFunc(t.hAlign)
	max := t.rs[headerRowIdx]
	for x := 0; x < max; x++ {
		if !t.noWhiteSpace {
			fmt.Fprint(t.out, conditionString(t.border.Left, t.pColumn, " "))
		}
		for y := 0; y <= end; y++ {
			v := t.cs[y]
			h := ""
			if y < len(t.headers) && x < len(t.headers[y]) {
				h = t.headers[y][x]
			}
			if t.autoFmt {
				h = title(h)
			}
			pad := conditionString(y == end && !t.border.Left, " ", t.pColumn)
			if t.noWhiteSpace {
				pad = conditionString(y == end && !t.border.Left, " ", t.tablePadding)
				fmt.Fprintf(t.out, "%s%s", pf(h, " ", v), pad)
			} else {
				fmt.Fprintf(t.out, " %s %s", pf(h, " ", v), pad)
			}
		}
		fmt.Fprint(t.out, t.newLine)
	}
	if t.hdrLine {
		t.printLine(true)
	}
}

func (t *table) printRow(columns [][]string, rowIdx int) {
	max := t.rs[rowIdx]
	total := len(columns)
	for i, line := range columns {
		pad := max - len(line)
		for n := 0; n < pad; n++ {
			columns[i] = append(columns[i], "  ")
		}
	}
	for x := 0; x < max; x++ {
		for y := 0; y < total; y++ {
			if !t.noWhiteSpace {
				fmt.Fprint(t.out, conditionString(!t.border.Left && y == 0, " ", t.pColumn))
				fmt.Fprint(t.out, " ")
			}
			str := columns[y][x]
			switch t.align {
			case alignCenter:
				fmt.Fprint(t.out, padCenter(str, " ", t.cs[y]))
			case alignRight:
				fmt.Fprint(t.out, padLeft(str, " ", t.cs[y]))
			case alignLeft:
				fmt.Fprint(t.out, padRight(str, " ", t.cs[y]))
			default:
				trimmed := strings.TrimSpace(str)
				if decimalRe.MatchString(trimmed) || percentRe.MatchString(trimmed) {
					fmt.Fprint(t.out, padLeft(str, " ", t.cs[y]))
				} else {
					fmt.Fprint(t.out, padRight(str, " ", t.cs[y]))
				}
			}
			if !t.noWhiteSpace {
				fmt.Fprint(t.out, " ")
			} else {
				fmt.Fprint(t.out, t.tablePadding)
			}
		}
		if !t.noWhiteSpace {
			fmt.Fprint(t.out, conditionString(t.border.Left, t.pColumn, " "))
		}
		fmt.Fprint(t.out, t.newLine)
	}
}
EOF"}

