// Package render prints lists of profiles in different formats.
package render

import (
	"encoding/json"
	"fmt"
	"io"
)

// Output types.
const (
	TableType    = "table"
	RawType      = "raw"
	MarkdownType = "markdown"
	JSONType     = "json"
)

// Row is a single line of output.
type Row struct {
	Profile string
	Status  string
	IP      string
	Host    string
}

// Renderer collects rows and prints them.
type Renderer interface {
	AppendRow(r Row)
	AddSeparator()
	NumRows() int
	Render() error
}

// Options configure a renderer.
type Options struct {
	Type    string
	Columns []string
	Writer  io.Writer
}

// TypeFromString maps the user value of --out to an output type.
func TypeFromString(s string) string {
	switch s {
	case "raw":
		return RawType
	case "markdown", "md":
		return MarkdownType
	case "json":
		return JSONType
	}
	return TableType
}

// New returns the renderer for the given options.
func New(opts Options) Renderer {
	if opts.Type == JSONType {
		return &jsonRenderer{w: opts.Writer}
	}
	t := newTable(opts.Writer)
	switch opts.Type {
	case MarkdownType:
		t.border = borders{Left: true, Top: false, Right: true, Bottom: false}
		t.pCenter = "|"
		t.autoWrap = false
	case RawType:
		t.autoWrap = false
		t.hAlign = alignLeft
		t.align = alignLeft
		t.pCenter = ""
		t.pColumn = ""
		t.pRow = ""
		t.hdrLine = false
		t.border = borders{}
		t.tablePadding = "\t"
		t.noWhiteSpace = true
	}
	return &tableRenderer{t: t, columns: opts.Columns, raw: opts.Type == RawType}
}

type tableRenderer struct {
	t       *table
	columns []string
	raw     bool
	rows    int
}

func (r *tableRenderer) AppendRow(row Row) {
	var cells []string
	for _, c := range r.columns {
		switch c {
		case "profile":
			cells = append(cells, row.Profile)
		case "status":
			cells = append(cells, row.Status)
		case "ip":
			cells = append(cells, row.IP)
		case "domain":
			cells = append(cells, row.Host)
		}
	}
	if len(cells) == 0 {
		return
	}
	r.t.append(cells)
	r.rows++
}

func (r *tableRenderer) AddSeparator() {
	if r.raw {
		return
	}
	r.t.addSeparator()
}

func (r *tableRenderer) NumRows() int { return r.rows }

func (r *tableRenderer) Render() error {
	if r.rows == 0 {
		return nil
	}
	r.t.setHeader(r.columns)
	r.t.render()
	return nil
}

type jsonRenderer struct {
	w    io.Writer
	rows []Row
}

func (r *jsonRenderer) AppendRow(row Row) { r.rows = append(r.rows, row) }
func (r *jsonRenderer) AddSeparator()     {}
func (r *jsonRenderer) NumRows() int      { return len(r.rows) }

func (r *jsonRenderer) Render() error {
	b, err := json.Marshal(r.rows)
	if err != nil {
		return err
	}
	_, err = fmt.Fprintln(r.w, string(b))
	return err
}
EOF"}

