// Package ui prints user facing messages.
package ui

import (
	"fmt"
	"io"
	"os"
	"syscall"
	"unsafe"
)

// NoColor disables colored output.
var NoColor = os.Getenv("TERM") == "dumb" || !isTerminal(os.Stdout.Fd())

// Quiet disables all non essential output.
var Quiet = false

// Out is where messages are written.
var Out io.Writer = os.Stdout

func isTerminal(fd uintptr) bool {
	var termios syscall.Termios
	_, _, errno := syscall.Syscall6(syscall.SYS_IOCTL, fd, syscall.TCGETS, uintptr(unsafe.Pointer(&termios)), 0, 0, 0)
	return errno == 0
}

func colorize(code, s string) string {
	if NoColor {
		return s
	}
	return "\x1b[" + code + "m" + s + "\x1b[0m"
}

// Info prints an informative message.
func Info(format string, a ...interface{}) {
	if Quiet {
		return
	}
	fmt.Fprintf(Out, "[%s] %s\n\n", colorize("1;36", "ℹ"), fmt.Sprintf(format, a...))
}

// Success prints a message for a successful action.
func Success(format string, a ...interface{}) {
	if Quiet {
		return
	}
	fmt.Fprintf(Out, "[%s] %s\n\n", colorize("1;32", "✔"), fmt.Sprintf(format, a...))
}

// Error prints an error message. It is printed even in quiet mode.
func Error(err error) {
	fmt.Fprintf(Out, "[%s] error: %s\n", colorize("1;31", "✖"), err.Error())
}

// Println prints a new line unless quiet mode is enabled.
func Println() {
	if Quiet {
		return
	}
	fmt.Fprintln(Out)
}
EOF"}

