// Package docker implements a tiny client for the Docker Engine API and
// the docker-compose file handling needed to sync profiles.
package docker

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net"
	"net/http"
	"net/url"
	"os"
	"sort"
	"strings"
	"time"
)

const (
	defaultHost       = "unix:///var/run/docker.sock"
	defaultAPIVersion = "1.42"
)

// Client talks to a docker daemon.
type Client struct {
	host     string
	proto    string
	addr     string
	basePath string
	version  string
	http     *http.Client
}

// Endpoint is the network configuration of a container.
type Endpoint struct {
	IPAddress string `json:"IPAddress"`
	NetworkID string `json:"NetworkID"`
}

// Container is the summary of a running container.
type Container struct {
	ID              string   `json:"Id"`
	Names           []string `json:"Names"`
	NetworkSettings struct {
		Networks map[string]Endpoint `json:"Networks"`
	} `json:"NetworkSettings"`
}

// SortedNetworks returns the networks of the container sorted by name.
func (c Container) SortedNetworks() []Endpoint {
	keys := make([]string, 0, len(c.NetworkSettings.Networks))
	for k := range c.NetworkSettings.Networks {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	var list []Endpoint
	for _, k := range keys {
		list = append(list, c.NetworkSettings.Networks[k])
	}
	return list
}

// Network is the summary of a docker network.
type Network struct {
	Name string `json:"Name"`
	ID   string `json:"Id"`
}

// NewClientFromEnv creates a client configured from DOCKER_* variables.
func NewClientFromEnv() (*Client, error) {
	host := os.Getenv("DOCKER_HOST")
	if host == "" {
		host = defaultHost
	}
	parts := strings.SplitN(host, "://", 2)
	if len(parts) == 1 {
		return nil, fmt.Errorf("unable to parse docker host `%s`", host)
	}
	proto, addr := parts[0], parts[1]
	basePath := ""
	if proto == "tcp" {
		u, err := url.Parse("tcp://" + addr)
		if err != nil {
			return nil, err
		}
		addr = u.Host
		basePath = u.Path
	}
	version := os.Getenv("DOCKER_API_VERSION")
	if version == "" {
		version = defaultAPIVersion
	}
	c := &Client{host: host, proto: proto, addr: addr, basePath: basePath, version: version}

	transport := &http.Transport{}
	switch proto {
	case "unix":
		transport.DisableCompression = true
		transport.DialContext = func(ctx context.Context, _, _ string) (net.Conn, error) {
			d := net.Dialer{Timeout: 32 * time.Second}
			return d.DialContext(ctx, "unix", addr)
		}
	case "npipe":
		return nil, fmt.Errorf("protocol not available")
	default:
		transport.DialContext = (&net.Dialer{Timeout: 32 * time.Second}).DialContext
	}
	c.http = &http.Client{Transport: transport}
	return c, nil
}

func (c *Client) connectionFailed() error {
	return fmt.Errorf("Cannot connect to the Docker daemon at %s. Is the docker daemon running?", c.host)
}

func (c *Client) get(path string, query url.Values, out interface{}) error {
	u := url.URL{Scheme: "http", Host: c.addr, Path: c.basePath + "/v" + c.version + path}
	if c.proto == "unix" {
		u.Host = "docker"
	}
	if query != nil {
		u.RawQuery = query.Encode()
	}
	req, err := http.NewRequest(http.MethodGet, u.String(), nil)
	if err != nil {
		return err
	}
	if c.proto == "unix" {
		req.Host = "docker"
	}
	resp, err := c.http.Do(req)
	if err != nil {
		var nerr net.Error
		if errors.As(err, &nerr) {
			if nerr.Timeout() || strings.Contains(err.Error(), "connection refused") || strings.Contains(err.Error(), "dial unix") {
				var operr *net.OpError
				if errors.As(err, &operr) && os.IsPermission(operr.Err) {
					return fmt.Errorf("permission denied while trying to connect to the Docker daemon socket at %v: %w", c.host, err)
				}
				return c.connectionFailed()
			}
		}
		return fmt.Errorf("error during connect: %w", err)
	}
	defer resp.Body.Close()
	body, err := io.ReadAll(resp.Body)
	if err != nil {
		return err
	}
	if resp.StatusCode < 200 || resp.StatusCode >= 400 {
		if len(body) == 0 {
			return fmt.Errorf("request returned %s for API route and version %s, check if the server supports the requested API version", http.StatusText(resp.StatusCode), u.String())
		}
		msg := strings.TrimSpace(string(body))
		if strings.Contains(resp.Header.Get("Content-Type"), "application/json") {
			var e struct {
				Message string `json:"message"`
			}
			if err := json.Unmarshal(body, &e); err != nil {
				return fmt.Errorf("Error reading JSON: %w", err)
			}
			msg = strings.TrimSpace(e.Message)
		}
		return fmt.Errorf("Error response from daemon: %s", msg)
	}
	return json.Unmarshal(body, out)
}

// NetworkID returns the id of a network given its name or id.
func (c *Client) NetworkID(network string) (string, error) {
	var list []Network
	if err := c.get("/networks", nil, &list); err != nil {
		return "", err
	}
	for _, n := range list {
		if n.Name == network || n.ID == network {
			return n.ID, nil
		}
	}
	return "", fmt.Errorf("unknown network ID: '%s'", network)
}

// RunningContainers lists running containers, optionally filtered by network id.
func (c *Client) RunningContainers(networkID string) ([]Container, error) {
	filters := map[string]map[string]bool{"status": {"running": true}}
	if networkID != "" {
		filters["network"] = map[string]bool{networkID: true}
	}
	b, err := json.Marshal(filters)
	if err != nil {
		return nil, err
	}
	q := url.Values{}
	q.Set("filters", string(b))
	var list []Container
	if err := c.get("/containers/json", q, &list); err != nil {
		return nil, err
	}
	return list, nil
}

// ContainerName returns the name of the container without slashes.
func ContainerName(c Container) string {
	return strings.Replace(c.Names[0], "/", "", -1)
}
