	errMissingProfile = errors.New("missing profile name")
	errDefaultProfile = errors.New("'default' profile should not be handled by hostctl")
	errOnlyOneProfile = errors.New("specify only one profile")
	errNotEmptyAll    = errors.New("args must be empty with --all flag")
)

var defaultColumns = []string{"profile", "status", "ip", "domain"}

func containsDefault(args []string) bool {
	for _, a := range args {
		if a == hosts.DefaultProfile {
			return true
		}
	}
	return false
}

func contains(list []string, s string) bool {
	for _, v := range list {
		if v == s {
			return true
		}
	}
	return false
}

// profilesArgs validates a list of profiles.
func profilesArgs(cmd *cobra.Command, args []string) error {
	if len(args) == 0 {
		return errMissingProfile
	}
	if containsDefault(args) {
		return errDefaultProfile
	}
	return nil
}

// profilesOrAllArgs validates a list of profiles or the --all flag.
func profilesOrAllArgs(cmd *cobra.Command, args []string) error {
	all, _ := cmd.Flags().GetBool("all")
	if all && len(args) > 0 {
		return errNotEmptyAll
	}
	if !all && len(args) == 0 {
		return errMissingProfile
	}
	if containsDefault(args) {
		return errDefaultProfile
	}
	return nil
}

// singleProfileArgs validates that exactly one profile is given.
func singleProfileArgs(cmd *cobra.Command, args []string) error {
	if len(args) == 0 {
		return errMissingProfile
	}
	if len(args) > 1 {
		return errOnlyOneProfile
	}
	if containsDefault(args) {
		return errDefaultProfile
	}
	return nil
}

// globals holds the values of the persistent flags.
type globals struct {
	hostFile string
	columns  []string
	output   string
}

func getGlobals(cmd *cobra.Command) globals {
	hostFile, _ := cmd.Flags().GetString("host-file")
	columns, _ := cmd.Flags().GetStringSlice("column")
	out, _ := cmd.Flags().GetString("out")
	raw, _ := cmd.Flags().GetBool("raw")
	output := render.TypeFromString(out)
	if raw {
		output = render.RawType
	}
	if len(columns) == 0 {
		columns = defaultColumns
	}
	return globals{hostFile: hostFile, columns: columns, output: output}
}

func loadHosts(path string) (*hosts.Content, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer f.Close()
	return hosts.Parse(f)
}

func writeHosts(path string, c *hosts.Content) error {
	f, err := os.OpenFile(path, os.O_WRONLY|os.O_TRUNC|os.O_CREATE, 0644)
	if err != nil {
		return err
	}
	if _, err := f.Write(c.Bytes()); err != nil {
		f.Close()
		return err
	}
	return f.Close()
}

// saveAndReload writes the content and parses the file again.
func saveAndReload(path string, c *hosts.Content) (*hosts.Content, error) {
	if err := writeHosts(path, c); err != nil {
		return nil, err
	}
	return loadHosts(path)
}

func newRenderer(g globals, columns []string) render.Renderer {
	return render.New(render.Options{Type: g.output, Columns: columns, Writer: os.Stdout})
}

func profileRows(p *hosts.Profile) []render.Row {
	var rows []render.Row
	for _, key := range p.IPList {
		r := p.Routes[key]
		for _, h := range r.HostNames {
			rows = append(rows, render.Row{Profile: p.Name, Status: p.Status, IP: key, Host: h})
		}
	}
	return rows
}

func defaultRows(c *hosts.Content) []render.Row {
	var rows []render.Row
	for _, l := range c.Default {
		if !l.IsRoute {
			continue
		}
		rows = append(rows, render.Row{Profile: hosts.DefaultProfile, Status: l.Status, IP: l.IP.String(), Host: l.Host})
	}
	return rows
}

// listProfiles prints the routes of the selected profiles.
func listProfiles(g globals, c *hosts.Content, filter []string, status string) error {
	r := newRenderer(g, g.columns)
	addGroup := func(rows []render.Row) {
		if len(rows) == 0 {
			return
		}
		if r.NumRows() > 0 {
			r.AddSeparator()
		}
		for _, row := range rows {
			r.AppendRow(row)
		}
	}
	if len(filter) == 0 || contains(filter, hosts.DefaultProfile) {
		addGroup(defaultRows(c))
	}
	for _, name := range c.ProfileNames {
		if len(filter) > 0 && !contains(filter, name) {
			continue
		}
		p := c.Profiles[name]
		if status != "" && p.Status != status {
			continue
		}
		addGroup(profileRows(p))
	}
	return r.Render()
}

// listStatus prints the name and status of the selected profiles.
func listStatus(g globals, c *hosts.Content, filter []string) error {
	r := newRenderer(g, []string{"profile", "status"})
	for _, name := range c.ProfileNames {
		if len(filter) > 0 && !contains(filter, name) {
			continue
		}
		p := c.Profiles[name]
		r.AppendRow(render.Row{Profile: p.Name, Status: p.Status})
	}
	return r.Render()
}

// postAction prints an empty line and, when a wait duration is given,
// waits for it (or a signal) before running the reverse action.
func postAction(wait time.Duration, action string, args []string, reverse func() error) error {
	ui.Println()
	if wait <= 0 {
		return nil
	}
	ui.Info("Waiting for %s or ctrl+c to %s from profile '%s'\n", wait, action, strings.Join(args, ", "))
	waitSignalOrDuration(wait)
	fmt.Println()
	return reverse()
}

func waitSignalOrDuration(d time.Duration) {
	ch := make(chan os.Signal, 1)
	signal.Notify(ch, os.Interrupt, syscall.SIGTERM)
	defer signal.Stop(ch)
	t := time.NewTimer(d)
	defer t.Stop()
	select {
	case <-ch:
	case <-t.C:
	}
}
